mapper.select:
SELECT EXISTS(
    SELECT 1 FROM post_like
    WHERE post_code = #{postCode}
      AND user_code = #{userCode}::uuid
)

mapper.delete:
DELETE FROM post_like
WHERE post_code = #{postCode}
  AND user_code = #{userCode}::uuid

mapper.update:
UPDATE post_comment
SET comment_status = 'DELETED'
WHERE comment_code = #{commentCode}
